import assert from "node:assert/strict";
import { mkdtemp, mkdir, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { resolve } from "node:path";
import { indexContent, } from "../../indexer/contentIndex.js";
const repositoryRoot = await mkdtemp(resolve(tmpdir(), "lifeos-content-index-"));
await mkdir(resolve(repositoryRoot, "src"), { recursive: true });
await writeFile(resolve(repositoryRoot, "src/test.ts"), Array.from({ length: 100 }, (_, index) => `const value${index} = ${index};`).join("\n"), "utf8");
const first = await indexContent(repositoryRoot);
assert.equal(first.files, 1);
assert.equal(first.cacheHits, 0);
assert.equal(first.indexed, 1);
assert.ok(first.chunks > 0);
const second = await indexContent(repositoryRoot);
assert.equal(second.files, 1);
assert.equal(second.cacheHits, 1);
assert.equal(second.indexed, 0);
assert.equal(second.chunks, first.chunks);
console.log("Content index test passed");
console.log(`Files: ${second.files}`);
console.log(`Chunks: ${second.chunks}`);
console.log(`Cache hits: ${second.cacheHits}`);
